                forwarded = policy.copy()
                if len(edge["resource"]) > len(forwarded["resource"]):
                    forwarded["resource"] = edge["resource"]
                if edge["action"] != "*":
                    forwarded["action"] = edge["action"]
                inherited.append(forwarded)
            pending.append([sender, distance + 1])
